/**
 * Manages the agent's long-term memory, built on DuckDB.
 * This class implements the "Geo-Contextual Knowledge Store" (GCKS) architecture,
 * which is divided into an Episodic (conversational) Layer and a Semantic (factual) Layer.
 */
class MemoryManager {
  /**
   * @param {object} duckdbConnection - An initialized DuckDB connection wrapper.
   * @param {object} embeddingManager - An initialized EmbeddingManager instance.
   */
  constructor(duckdbConnection, embeddingManager) {
    this.db = duckdbConnection;
    this.embeddingManager = embeddingManager;
    this.ready = false;
    // A promise that resolves when the memory tables are ready.
    this.readyPromise = this._initialize();
  }

  /**
   * Initializes the memory system by creating the necessary tables in DuckDB.
   * This function is idempotent and can be safely called multiple times.
   * @private
   */
  async _initialize() {
    try {
      console.log("MemoryManager: Initializing memory store...");

      // Layer 2: Semantic/Factual Layer (Geospatial Knowledge Graph)
      await this.db.query(`
        CREATE TABLE IF NOT EXISTS entities (
            entity_id UUID PRIMARY KEY,
            entity_name VARCHAR,
            entity_type VARCHAR, -- e.g., 'Restaurant', 'Address', 'User', 'GeographicRegion',
            UNIQUE(entity_name, entity_type),
            created_at TIMESTAMP DEFAULT current_timestamp
        );`);

      await this.db.query(`
        CREATE TABLE IF NOT EXISTS entity_attributes (
            attribute_id UUID PRIMARY KEY,
            entity_id UUID REFERENCES entities(entity_id),
            attribute_key VARCHAR,
            attribute_value VARCHAR,
            UNIQUE(entity_id, attribute_key),
            created_at TIMESTAMP DEFAULT current_timestamp
        );`);

      await this.db.query(`
        CREATE TABLE IF NOT EXISTS geospatial_attributes (
            geo_id UUID PRIMARY KEY,
            entity_id UUID REFERENCES entities(entity_id) UNIQUE,
            geometry GEOMETRY, -- Uses the GEOMETRY type from the spatial extension
            created_at TIMESTAMP DEFAULT current_timestamp
        );`);

      await this.db.query(`
        CREATE TABLE IF NOT EXISTS relationships (
            relationship_id UUID PRIMARY KEY,
            source_entity_id UUID REFERENCES entities(entity_id),
            target_entity_id UUID REFERENCES entities(entity_id),
            relationship_type VARCHAR, -- e.g., 'has_location', 'near', 'serves_cuisine',
            UNIQUE(source_entity_id, target_entity_id, relationship_type),
            created_at TIMESTAMP DEFAULT current_timestamp
        );`);

      // Layer 1: Episodic/Conversational Layer (Vector Store)
      await this.db.query(`
        CREATE TABLE IF NOT EXISTS conversation_chunks (
            chunk_id UUID PRIMARY KEY,
            session_id VARCHAR,
            turn INTEGER,
            speaker VARCHAR, -- 'user' or 'agent'
            content TEXT,
            embedding FLOAT[384], -- DuckDB requires vector dimensions
            created_at TIMESTAMP DEFAULT current_timestamp
        );`);

      // --- PERFORMANCE FIX: Add indexes to memory tables ---
      // These indexes are crucial for fast retrieval as the memory grows.
      // Using "IF NOT EXISTS" makes this operation idempotent.
      console.log("MemoryManager: Creating indexes for performance. This may take a moment on first run...");

      // Index for semantic (vector) search on conversations.
      await this.db.query(`
        CREATE INDEX IF NOT EXISTS idx_conversation_embedding ON conversation_chunks USING HNSW (embedding);
      `);

      // Index for fast entity lookup by name.
      await this.db.query(`
        CREATE INDEX IF NOT EXISTS idx_entity_name ON entities (entity_name);
      `);

      // Spatial index for fast geospatial queries.
      await this.db.query(`
        CREATE INDEX IF NOT EXISTS idx_geospatial_geometry ON geospatial_attributes USING RTREE (geometry);
      `);

      this.ready = true;
      console.log("MemoryManager: Memory store initialized successfully.");
    } catch (error) {
      console.error("MemoryManager: Failed to initialize memory tables", error);
      this.ready = false;
      throw error;
    }
  }

  /**
   * Adds a conversational turn to the episodic memory.
   * @param {object} turnData - The conversational turn data.
   * @param {string} turnData.session_id - The ID of the current session.
   * @param {number} turnData.turn - The turn number in the conversation.
   * @param {string} turnData.speaker - 'user' or 'agent'.
   * @param {string} turnData.content - The text content of the turn.
   */
  async addEpisodicMemory(turnData) {
    try {
      if (!this.ready) await this.readyPromise;

      const { session_id, turn, speaker, content } = turnData;

      // Don't store empty or whitespace-only content to avoid noise in memory.
      if (!content || content.trim() === "") {
        // console.log("MemoryManager: Skipping empty content for episodic memory.");
        return;
      }

      // To prevent SQL injection, we must escape single quotes in the content string.
      const escapedContent = content.replace(/'/g, "''");

      // 1. Generate embedding for the content.
      const embedding = await this.embeddingManager.generateEmbedding(content);
      const embeddingString = JSON.stringify(Array.from(embedding));

      // 2. Prepare the INSERT statement by interpolating all values directly.
      // This avoids a driver quirk with mixed parameter types (placeholders and injected values).
      // The content is escaped to prevent SQL injection.
      const query = `
        INSERT INTO conversation_chunks (chunk_id, session_id, turn, speaker, content, embedding)
        VALUES (uuid(), '${session_id}', ${turn}, '${speaker}', '${escapedContent}', CAST('${embeddingString}' AS FLOAT[384]));
      `;

      // Execute the query without parameters, as all values are now part of the query string.
      await this.db.query(query);

      console.log(`MemoryManager: Added episodic memory for turn ${turn} by ${speaker}.`);
    } catch (error) {
      console.error("MemoryManager: Failed to add episodic memory.", {
        turnData,
        error,
      });
      // We don't re-throw, as failing to save memory shouldn't crash the agent's main loop.
    }
  }

  /**
   * Retrieves relevant conversational turns from episodic memory using semantic search.
   * @param {string} queryText - The text to search for.
   * @param {string} sessionId - The ID of the current session to scope the search.
   * @param {number} [topK=3] - The number of most relevant turns to retrieve.
   * @returns {Promise<Array<object>>} A promise that resolves to an array of conversation chunks.
   */
  async retrieveEpisodicMemory(queryText, sessionId, topK = 3) {
    try {
      if (!this.ready) await this.readyPromise;

      // Don't search for empty or whitespace-only text.
      if (!queryText || queryText.trim() === "") {
        return [];
      }

      // 1. Generate an embedding for the query text.
      const queryEmbedding = await this.embeddingManager.generateEmbedding(queryText);
      const queryEmbeddingString = JSON.stringify(Array.from(queryEmbedding));

      // 2. Prepare the SQL query for vector similarity search.
      // All dynamic values are interpolated directly into the query string.
      // This is safe as sessionId is a UUID and topK is a number, and it avoids
      // a driver quirk with mixed parameter types.
      const query = `
        SELECT
            content,
            speaker,
            turn,
            array_cosine_distance(embedding, CAST('${queryEmbeddingString}' AS FLOAT[384])) AS distance
        FROM
            conversation_chunks
        WHERE
            session_id = '${sessionId}'
        ORDER BY
            distance ASC
        LIMIT ${topK};
      `;

      // 3. Execute the query without parameters.
      const results = await this.db.query(query);

      console.log(`MemoryManager: Retrieved ${results.numRows} relevant episodic memories for query: "${queryText}"`);

      // 4. Convert the Apache Arrow result to an array of plain JavaScript objects.
      return results.toArray().map(row => row.toJSON());
    } catch (error) {
      console.error("MemoryManager: Failed to retrieve episodic memory.", { queryText, error });
      // Return an empty array on failure so the agent can proceed without memory context.
      return [];
    }
  }

  /**
   * Adds structured facts (entities, attributes, relationships) to the semantic memory.
   * @param {object} facts - The structured facts to add.
   */
  async addSemanticFacts(facts) {
    if (!this.ready) await this.readyPromise;
    if (!facts || (!facts.entities && !facts.relationships)) {
      console.log("MemoryManager: addSemanticFacts called with no facts to add.");
      return;
    }

    console.log("MemoryManager: Consolidating semantic facts into knowledge graph...", facts);

    try {
      // Use a transaction to ensure all facts are added atomically
      await this.db.query('BEGIN TRANSACTION;');

      const entityNameToIdMap = new Map();

      // 1. Process Entities and their Attributes
      if (facts.entities) {
        for (const entity of facts.entities) {
          // --- ROBUSTNESS FIX ---
          // Validate that the entity has the required fields before processing.
          if (!entity.name || !entity.type) {
            console.warn("MemoryManager: Skipping entity with missing name or type.", entity);
            continue; // Skip this malformed entity
          }

          // "Get or Create" pattern to robustly find or insert an entity and get its ID.
          // This avoids a persistent issue with INSERT..ON CONFLICT..RETURNING in the driver.
          let entityId;
          const selectQuery = `SELECT entity_id FROM entities WHERE entity_name = ? AND entity_type = ?;`;
          const selectResult = await this.db.query(selectQuery, [entity.name, entity.type]);

          if (selectResult.numRows > 0) {
            // Entity exists, use its ID
            entityId = selectResult.get(0).toJSON().entity_id;
          } else {
            // Entity does not exist, insert it and get the new ID
            const insertQuery = `
              INSERT INTO entities (entity_id, entity_name, entity_type)
              VALUES (uuid(), ?, ?)
              RETURNING entity_id;
            `;
            const insertResult = await this.db.query(insertQuery, [entity.name, entity.type]);
            entityId = insertResult.get(0).toJSON().entity_id;
          }

          entityNameToIdMap.set(entity.name, entityId);

          // Process simple attributes
          if (entity.attributes) {
            for (const [key, value] of Object.entries(entity.attributes)) {
              const attrQuery = `
                INSERT INTO entity_attributes (attribute_id, entity_id, attribute_key, attribute_value)
                VALUES (uuid(), ?, ?, ?)
                ON CONFLICT (entity_id, attribute_key)
                DO UPDATE SET attribute_value = excluded.attribute_value;
              `;
              await this.db.query(attrQuery, [entityId, key, String(value)]);
            }
          }

          // Process geospatial attributes
          if (entity.geometry) {
            // WKT strings don't typically have single quotes, but we escape them for safety.
            const escapedGeometry = entity.geometry.replace(/'/g, "''");
            const geoQuery = `
              INSERT INTO geospatial_attributes (geo_id, entity_id, geometry)
              VALUES (uuid(), '${entityId}', ST_GeomFromText('${escapedGeometry}'))
              ON CONFLICT (entity_id)
              DO UPDATE SET geometry = excluded.geometry;
            `;
            // Execute the query without parameters, as all values are now safely part of the query string.
            await this.db.query(geoQuery);
          }
        }
      }

      // 2. Process Relationships
      if (facts.relationships) {
        for (const rel of facts.relationships) {
          const sourceId = entityNameToIdMap.get(rel.source);
          const targetId = entityNameToIdMap.get(rel.target);

          if (sourceId && targetId) {
            const relQuery = `
              INSERT INTO relationships (relationship_id, source_entity_id, target_entity_id, relationship_type)
              VALUES (uuid(), ?, ?, ?)
              ON CONFLICT (source_entity_id, target_entity_id, relationship_type)
              DO NOTHING;
            `;
            await this.db.query(relQuery, [sourceId, targetId, rel.type]);
          } else {
            console.warn(`MemoryManager: Could not create relationship due to missing entity. Source: '${rel.source}', Target: '${rel.target}'`);
          }
        }
      }

      await this.db.query('COMMIT;');
      console.log("MemoryManager: Semantic facts successfully consolidated.");

    } catch (error) {
      console.error("MemoryManager: Failed to add semantic facts. Rolling back transaction.", { facts, error });
      await this.db.query('ROLLBACK;');
      // We don't re-throw, as failing to save memory shouldn't crash the agent.
    }
  }

  /**
   * Retrieves structured facts for given entities from semantic memory.
   * @param {Array<string>} entityNames - An array of entity names to look up.
   * @returns {Promise<object|null>} A promise that resolves to an object containing the facts, or null if none found.
   */
  async retrieveSemanticFacts(entityNames) {
    if (!this.ready) await this.readyPromise;
    if (!entityNames || entityNames.length === 0) {
      return null;
    }

    console.log("MemoryManager: Retrieving semantic facts for entities:", entityNames);
    const facts = {};

    try {
      // To avoid SQL injection and handle names with single quotes, we escape them
      // and build the list for the IN clause manually. This avoids parameter binding
      // issues with array types in the wasm driver.
      const escapedEntityNames = entityNames.map(name => `'${name.replace(/'/g, "''")}'`).join(',');

      // Query 1: Get entities, their attributes, and geometries
      const entityDetailsQuery = `
        SELECT
          e.entity_name,
          e.entity_type,
          a.attribute_key,
          a.attribute_value,
          ST_AsText(g.geometry) AS geometry_wkt
        FROM entities e
        LEFT JOIN entity_attributes a ON e.entity_id = a.entity_id
        LEFT JOIN geospatial_attributes g ON e.entity_id = g.entity_id
        WHERE e.entity_name IN (${escapedEntityNames});
      `;
      const entityDetailsResult = await this.db.query(entityDetailsQuery);
      const entityRows = entityDetailsResult.toArray().map(row => row.toJSON());

      if (entityRows.length === 0) {
        console.log("MemoryManager: No semantic facts found for the given entities.");
        return null;
      }

      // Process entity details into the facts object
      for (const row of entityRows) {
        const { entity_name, entity_type, attribute_key, attribute_value, geometry_wkt } = row;
        if (!facts[entity_name]) {
          facts[entity_name] = {
            type: entity_type,
            attributes: {},
            relationships: [], // Initialize empty
            geometry: geometry_wkt || null
          };
        }
        if (attribute_key && attribute_value) {
          facts[entity_name].attributes[attribute_key] = attribute_value;
        }
      }

      // Query 2: Get relationships involving these entities
      const relationshipsQuery = `
        SELECT
          r.relationship_type,
          source.entity_name as source_name,
          target.entity_name as target_name
        FROM relationships r
        JOIN entities source ON r.source_entity_id = source.entity_id
        JOIN entities target ON r.target_entity_id = target.entity_id
        WHERE
          source.entity_name IN (${escapedEntityNames}) OR
          target.entity_name IN (${escapedEntityNames});
      `;
      const relationshipsResult = await this.db.query(relationshipsQuery);
      const relationshipRows = relationshipsResult.toArray().map(row => row.toJSON());

      // Process and add relationships to the facts object
      for (const row of relationshipRows) {
        const { source_name, target_name, relationship_type } = row;
        // Add relationship to source entity if it's in our list of targets
        if (facts[source_name]) {
          const relString = `${relationship_type} -> ${target_name}`;
          if (!facts[source_name].relationships.includes(relString)) {
            facts[source_name].relationships.push(relString);
          }
        }
      }

      console.log("MemoryManager: Retrieved and structured semantic facts:", facts);
      return Object.keys(facts).length > 0 ? facts : null;

    } catch (error) {
      console.error("MemoryManager: Failed to retrieve semantic facts.", { entityNames, error });
      return null;
    }
  }
}

export default MemoryManager;
