import $ from "jquery";
// 15Apr2024 import Handlebars from "Handlebars";
import Handlebars, { W } from "handlebars/dist/handlebars"; // 15Apr2024
import * as duckdb from "@duckdb/duckdb-wasm";
import bootstrap from "bootstrap/dist/js/bootstrap";
import * as d3 from "d3";
import HelperUtil from "./modules/helperutils";
// Import WebLLM MLCEngine
import { CreateMLCEngine } from "@mlc-ai/web-llm";
// Import Orchestration Layer components
import StateManager from "./modules/orchestration/state_manager.js";
import CommunicationBus from "./modules/orchestration/communication_bus.js";
import ReActController from "./modules/orchestration/react_controller.js";
import EmbeddingManager from "./modules/orchestration/embedding_manager.js";
import ToolExecutor from "./modules/tools/tool_executor.js";
import InitializeDuckDB from "./modules/duckdb_init.js";

function Geointerpreter() {
  const publicAPI = {};
  let mHelperUtil;
  let mMediator;
  let mDB; // DuckDB database instance
  let mDBConnection; // DuckDB connection

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  /**
   * Requests persistent storage for the application's data (including cached models).
   * This prevents the browser from automatically clearing the cache when storage is low.
   */
  async function requestPersistentStorage() {
    if (navigator.storage && navigator.storage.persist) {
      const isPersisted = await navigator.storage.persisted();
      console.log(`Storage is currently persisted: ${isPersisted}`);
      if (!isPersisted) {
        try {
          const wasPersisted = await navigator.storage.persist();
          if (wasPersisted) {
            console.log(
              "Successfully enabled persistent storage for the origin."
            );
          } else {
            console.warn(
              "Failed to enable persistent storage. The browser may clear data under storage pressure."
            );
          }
        } catch (error) {
          console.error("Error requesting persistent storage:", error);
        }
      }
    } else {
      console.warn("Persistent Storage API is not supported in this browser.");
    }
  }
  // Main function to run our analysis
  async function initializeApplication() {
    const outputElement = document.getElementById("analysis-output");
    const userInputField = document.getElementById("user-input");
    const sendButton = document.getElementById("send-button");
    const cancelAnalysisButton = document.getElementById(
      "cancel-analysis-button"
    );
    const newSessionButton = document.getElementById("new-session-button");
    const chatHistoryDiv = document.getElementById("chat-history");
    const toggleThinkingButton = document.getElementById(
      "toggle-thinking-button"
    );
    const thinkingProcessContent = document.getElementById(
      "thinking-process-content"
    );
    const thinkingProcessWrapper = document.getElementById(
      "thinking-process-wrapper"
    );
    const chatInputContainer = document.getElementById("chat-input-container");
    // Get references to the new user prompt elements
    const userPromptContainer = document.getElementById(
      "user-prompt-container"
    );
    const userPromptQuestion = document.getElementById("user-prompt-question");
    const userPromptInput = document.getElementById("user-prompt-input");
    const userPromptSubmit = document.getElementById("user-prompt-submit");
    const userPromptOptions = document.getElementById("user-prompt-options");

    const typewriter = {
      queue: [],
      isTyping: false,
      speed: 10, // ms per character

      add(text) {
        // Add new text to the queue as individual characters
        // If this is the first text being added for a new thought, expand the UI.
        if (
          !this.isTyping &&
          thinkingProcessWrapper &&
          !thinkingProcessWrapper.classList.contains("show")
        ) {
          thinkingProcessCollapse.show();
        }

        this.queue.push(...text.split(""));
        // If not already typing, start
        if (!this.isTyping) {
          this.type();
        }
      },

      async type() {
        this.isTyping = true;
        while (this.queue.length > 0) {
          const char = this.queue.shift();
          thinkingProcessContent.textContent += char;

          // Fix: Scroll the thinking process content itself (it has the scrollbar)
          thinkingProcessContent.scrollTop =
            thinkingProcessContent.scrollHeight;

          await new Promise((resolve) => setTimeout(resolve, this.speed));
        }
        this.isTyping = false;
      },

      clear() {
        this.queue = [];
        thinkingProcessContent.textContent = "";
      },
    };

    // Initialize the Bootstrap Collapse instance once for efficiency.
    const thinkingProcessCollapse = new bootstrap.Collapse(
      thinkingProcessWrapper,
      {
        toggle: false,
      }
    );

    // Remove the manual event listener and let Bootstrap handle the toggle
    // toggleThinkingButton.addEventListener("click", () => {
    //   thinkingProcessCollapse.toggle();
    // });

    // Handle button text change on collapse toggle for the "Show Thinking" UI
    if (thinkingProcessWrapper && toggleThinkingButton) {
      thinkingProcessWrapper.addEventListener("show.bs.collapse", () => {
        toggleThinkingButton.innerHTML =
          'Hide Thinking <i class="bi bi-chevron-up toggle-icon"></i>';
      });

      thinkingProcessWrapper.addEventListener("hide.bs.collapse", () => {
        toggleThinkingButton.innerHTML =
          'Show Thinking <i class="bi bi-chevron-down toggle-icon"></i>';
      });
    }

    // Request persistent storage early in the lifecycle
    await requestPersistentStorage();

    let aiCore; // WebLLM MLCEngine instance
    const { db, dbConn } = await InitializeDuckDB();
    mDB = db;
    mDBConnection = dbConn;

    // Variables to track progress for both models
    let llmProgress = { text: "Starting...", percentage: 0 };
    let embeddingProgress = { text: "Starting...", percentage: 0 };

    // Function to update the UI with combined progress
    const updateCombinedProgress = () => {
      const llmMsg = `LLM (${modelId}): ${llmProgress.text} (${llmProgress.percentage}%)`;
      const embeddingMsg = `Embedding Model: ${embeddingProgress.text} (${embeddingProgress.percentage}%)`;
      outputElement.innerHTML = `Initializing AI systems...<br>${llmMsg}<br>${embeddingMsg}`;
    };

    // Callback for WebLLM progress
    const llmInitProgressCallback = (report) => {
      llmProgress.percentage = Math.round(report.progress * 100);
      llmProgress.text = report.text;
      updateCombinedProgress();
    };

    // Callback for EmbeddingManager progress (assuming EmbeddingManager supports this)
    // This would need to be implemented in modules/orchestration/embedding_manager.js
    const embeddingInitProgressCallback = (report) => {
      // Check if report.progress is a valid number before calculating percentage
      if (report && typeof report.progress === "number") {
        embeddingProgress.percentage = Math.round(report.progress * 100);
      } else {
        // Default to a meaningful value when progress is not available
        embeddingProgress.percentage = 0;
      }

      // Make sure text is always a string
      embeddingProgress.text = report && report.text ? report.text : "ready";

      updateCombinedProgress();
    };
    //  const modelId = "Phi-3-mini-4k-instruct-q4f16_1-MLC";
    // const modelId = "Phi-3-mini-4k-instruct-q4f32_1-MLC";
    //  const modelId = "Llama-3.2-3B-Instruct-q4f32_1-MLC";
    // const modelId = "Mistral-7B-Instruct-q4f32_1-MLC";
    // const modelId = "Qwen2-1.5B-Instruct-q4f32_1-MLC";
    // const modelId = "Qwen2-7B-Instruct-q4f32_1-MLC";

    // const modelId = "Llama-3.2-1B-Instruct-q4f16_1-MLC"; // small-fast
    const modelId = "Hermes-2-Pro-Llama-3-8B-q4f16_1-MLC"; // supports OpenAI's API for function calling

    try {
      outputElement.textContent = "Initializing AI systems...";

      // Start updating progress immediately
      updateCombinedProgress();

      // Parallel loading of models as per design document
      const embeddingManagerInstance = new EmbeddingManager(
        embeddingInitProgressCallback
      ); // Instantiate with callback
      const [core, _] = await Promise.all([
        // Await both promises concurrently
        CreateMLCEngine(modelId, {
          initProgressCallback: llmInitProgressCallback,
        }),
        embeddingManagerInstance.readyPromise, // Await the promise from the instance
      ]);

      aiCore = core;
      // The `_` variable captures the resolved value of `embeddingManagerInstance.readyPromise`,
      // which we don't directly need here as the instance itself is used.

      outputElement.textContent = "AI systems ready. Ask a question.";

      // Orchestration Layer instances
      const stateManager = new StateManager();
      const communicationBus = new CommunicationBus();
      let lastThinkingProcess = "";
      // Listen for the AI's streaming thought process
      communicationBus.addEventListener("aiThinkingStream", (event) => {
        const newThinkingProcess = event.detail.content;

        // If the new content is empty, it's a reset signal.
        if (newThinkingProcess === "") {
          typewriter.clear();
          lastThinkingProcess = "";
          return;
        }

        // Find the difference between the last known content and the new content
        const diff = newThinkingProcess.substring(lastThinkingProcess.length);

        if (diff) {
          // Add only the new text to the typewriter queue
          typewriter.add(diff);
        }

        // Update the last known content
        lastThinkingProcess = newThinkingProcess;
      });

      // Listen for agent status updates to show thinking/executing indicators
      stateManager.subscribe((state) => {
        // Update UI based on state.agentStatus
        console.log("Agent Status:", state.agentStatus);

        if (cancelAnalysisButton) {
          if (state.agentStatus === "idle") {
            cancelAnalysisButton.style.display = "none";
          } else {
            cancelAnalysisButton.style.display = "inline-block";
          }
        }

        if (state.agentStatus === "idle") {
          outputElement.textContent = "Ready for your questions.";
          userInputField.disabled = false;
          sendButton.disabled = false;
          chatInputContainer.style.display = "flex"; // Ensure main input is visible
          userPromptContainer.style.display = "none"; // Ensure prompt is hidden
        } else {
          outputElement.textContent = `Agent Status: ${state.agentStatus.replace(
            /_/g,
            " "
          )}...`;
          userInputField.disabled = true;
          sendButton.disabled = true;

          if (state.agentStatus !== "waiting_for_user") {
            chatInputContainer.style.display = "flex";
          }
        }

        // Update conversation history in UI
        chatHistoryDiv.innerHTML = ""; // Clear and re-render for simplicity
        state.conversationHistory.forEach((message) => {
          const role = message.role === "user" ? "You" : "GeoInterpreter";
          const messageClass =
            message.role === "tool"
              ? "tool-message"
              : `${message.role}-message`;
          // Defensive check for content to prevent errors if it's null/undefined
          const content = message.content || "";
          chatHistoryDiv.innerHTML += `<div class="message-container"><div class="${messageClass}"><strong>${role}:</strong> ${content.replace(
            /\n/g,
            "<br>"
          )}</div></div>`;
        });
        chatHistoryDiv.scrollTop = chatHistoryDiv.scrollHeight; // Scroll to bottom
      });

      // Instantiate the ToolExecutor with the DB connection
      const toolExecutorInstance = new ToolExecutor(mDBConnection);

      // Instantiate ReActController. This must happen AFTER the stateManager
      // subscription is set up, because the controller's constructor immediately
      // updates the state to 'idle', and we need the UI to catch that change.
      const reactController = new ReActController(
        stateManager,
        communicationBus,
        aiCore,
        // Pass the execute method, bound to the instance to preserve its `this` context
        { execute: toolExecutorInstance.execute.bind(toolExecutorInstance) },
        embeddingManagerInstance,
        mDBConnection
      );

      // Listen for final answer to update UI
      communicationBus.addEventListener("finalAnswerReady", (event) => {
        // The final answer is already added to history by the controller.
        // We just need to ensure the UI is in the final 'idle' state.
        outputElement.textContent = "Analysis complete."; // Update status
      });

      // Event listener for user input
      communicationBus.addEventListener("userQuerySubmitted", () => {
        // When a new query starts, clear the thinking process UI and the state
        typewriter.clear();
        lastThinkingProcess = "";
      });

      sendButton.addEventListener("click", () => {
        const userQueryText = userInputField.value.trim();
        if (userQueryText) {
          userInputField.value = ""; // Clear input field
          // Dispatch the user query to the ReActController
          communicationBus.dispatchEvent("userQuerySubmitted", {
            query: userQueryText,
          });
        }
      });

      userInputField.addEventListener("keypress", (event) => {
        if (event.key === "Enter") {
          sendButton.click(); // Simulate a click on the send button
        }
      });

      if (cancelAnalysisButton) {
        cancelAnalysisButton.addEventListener("click", () => {
          communicationBus.dispatchEvent("cancelProcessing");
        });
      }

      if (newSessionButton) {
        newSessionButton.addEventListener("click", () => {
          communicationBus.dispatchEvent("newSessionRequested");
        });
      }

      // Listen for the agent asking the user a question
      communicationBus.addEventListener("promptUserForInput", (event) => {
        const { question, options } = event.detail;

        // Show the prompt UI and hide the normal chat input
        chatInputContainer.style.display = "none";
        userPromptContainer.style.display = "block";
        userPromptQuestion.textContent = question;

        // Clear previous options and input
        userPromptOptions.innerHTML = "";
        userPromptInput.value = "";

        if (options && options.length > 0) {
          // If options are provided, create buttons and hide the text input
          userPromptInput.parentElement.style.display = "none";

          options.forEach((optionText) => {
            const button = document.createElement("button");
            button.textContent = optionText;
            button.className = "btn btn-outline-primary me-2 mb-2"; // Bootstrap styling
            button.addEventListener("click", () => {
              communicationBus.dispatchEvent("userInputProvided", {
                response: optionText,
              });
              userPromptContainer.style.display = "none"; // Hide after click
            });
            userPromptOptions.appendChild(button);
          });
        } else {
          // If no options, show the text input and submit button
          userPromptInput.parentElement.style.display = "block";
          userPromptInput.focus();
        }
      });

      // Handle submission from the text input prompt
      const submitUserResponse = () => {
        const response = userPromptInput.value.trim();
        if (response) {
          communicationBus.dispatchEvent("userInputProvided", { response });
          userPromptContainer.style.display = "none"; // Hide after submit
        }
      };

      userPromptSubmit.addEventListener("click", submitUserResponse);
      userPromptInput.addEventListener("keypress", (event) => {
        if (event.key === "Enter") submitUserResponse();
      });

      // Set initial state
      stateManager.updateState({ agentStatus: "idle" });
    } catch (error) {
      // Error handling remains the same
      console.error("Initialization error:", error);
      outputElement.textContent = `Error during initialization: ${error.message || "An unknown error occurred."}`;
      if (error.message && error.message.includes("Model variant not found")) {
        outputElement.textContent += `\n\nPlease ensure the model ID '${modelId}' is correct and available in WebLLM's model list.`;
      }
    } finally {
      // Unloading logic might be better handled on window close/page unload
    }
  }

  publicAPI.init = function () {
    mHelperUtil = new HelperUtil();
    // Check if DOM is already loaded
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", initializeApplication);
    } else {
      // DOM is already loaded, call function directly
      console.log("DOM already loaded, initializing application directly");
      initializeApplication();
    }

    // For debugging purposes
    console.log("Geointerpreter.init() called");
  };

  return publicAPI;
}
export default Geointerpreter;