/**
 * Finds places of interest near a given geographic point using the Overpass API.
 * @param {object} params - The parameters for the search.
 * @param {number} params.latitude - The latitude of the center point.
 * @param {number} params.longitude - The longitude of the center point.
 * @param {string} params.amenity - The type of place to search for (e.g., 'restaurant', 'hospital').
 * @param {string} [params.cuisine] - Optional cuisine type for restaurants.
 * @param {number} [params.radius_meters=1000] - The search radius in meters.
 * @returns {Promise<string>} A promise that resolves to a JSON string of found places with their name and coordinates.
 */
export async function findPlacesNearby(params) {
  const {
    latitude,
    longitude,
    amenity,
    cuisine,
    radius_meters = 1000,
  } = params;

  if (!latitude || !longitude || !amenity) {
    return "Error: Missing required parameters. 'latitude', 'longitude', and 'amenity' are required.";
  }

  // Build the Overpass QL query filters
  let filters = `["amenity"="${amenity}"]`;
  if (cuisine) {
    filters += `["cuisine"="${cuisine}"]`;
  }

  const query = `
    [out:json][timeout:25];
    (
      node${filters}(around:${radius_meters},${latitude},${longitude});
      way${filters}(around:${radius_meters},${latitude},${longitude});
      relation${filters}(around:${radius_meters},${latitude},${longitude});
    );
    out center;
  `;

  try {
    const response = await fetch("https://overpass-api.de/api/interpreter", {
      method: "POST",
      body: query,
    });

    if (!response.ok) {
      return `Error: Overpass API request failed with status ${response.status}.`;
    }

    const data = await response.json();
    const places = data.elements
      .map((el) => {
        if (el.tags && el.tags.name) {
          // For ways and relations, Overpass returns a 'center' object with lat/lon.
          // For nodes, it's directly lat/lon properties.
          const center = el.center || { lat: el.lat, lon: el.lon };
          if (center && typeof center.lat === 'number' && typeof center.lon === 'number') {
            return {
              name: el.tags.name,
              latitude: center.lat,
              longitude: center.lon,
            };
          }
        }
        return null;
      })
      .filter(Boolean); // Filter out elements without a name or coordinates

    if (places.length === 0) {
      return `Found 0 places matching the criteria within a ${radius_meters} meter radius.`;
    }

    // Return a JSON string so the AI can easily parse it for the next step.
    return JSON.stringify(places, null, 2);
  } catch (error) {
    console.error("Overpass API error:", error);
    return `Error executing Overpass query: ${error.message}`;
  }
}